import pg from 'pg';
import {writeFileSync} from 'node:fs';
import {AIMessage} from '@langchain/core/messages';
import {PostgresAgentSharedCost,SqliteAgentDefinitions,SqliteAgentTokenBudget,createConfiguredAgentRun} from '../../dist/index.js';
const phase=process.env.APP_MIXER_TEST_PHASE,runId=phase,scope={tenantId:'t',agentId:'agent'},actor={tenantId:'t',principalId:'service'},sharedScope={tenantId:'t',budgetId:phase,currency:'USD',maxMicros:1000};
const pool=new pg.Pool({connectionString:process.env.APP_MIXER_TEST_POSTGRES_URL,options:`-c search_path=${process.env.APP_MIXER_TEST_SCHEMA}`});
const hold=async label=>{process.send(label);await new Promise(()=>{});};let transactions=0;
const ledger=new PostgresAgentSharedCost({enabled:true,scope:sharedScope,authorize:()=>true,query:(sql,args)=>pool.query(sql,args),transaction:async operation=>{if(phase==='after-local-reserve'&&transactions===0)await hold(phase);const client=await pool.connect();try{await client.query('BEGIN');const value=await operation((sql,args)=>client.query(sql,args));if((phase==='before-shared-reserve-commit'&&transactions===0)||(phase==='before-shared-settle-commit'&&transactions===1))await hold(phase);await client.query('COMMIT');transactions++;if((phase==='after-shared-reserve'&&transactions===1)||(phase==='after-shared-settle'&&transactions===2))await hold(phase);return value;}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}}});
const definitions=new SqliteAgentDefinitions(':memory:'),manifest={manifestVersion:1,tenantId:'t',agentId:'agent',name:'Agent',owner:{kind:'organization',id:'org'},administrators:['admin'],servicePrincipalId:'service',model:{provider:'local',model:'test'},allowedCapabilities:[],lifecycle:{enabled:true,maxAttempts:3,runTimeoutMs:60000},quotas:{maxConcurrentRuns:1,maxTokensPerRun:100,maxRunsPerDay:10}};
definitions.save('t',manifest,0);const budget=new SqliteAgentTokenBudget(process.env.APP_MIXER_TEST_DB,{scope,runId,leaseToken:process.env.APP_MIXER_TEST_LEASE,maxTokens:100,cost:{currency:'USD',maxMicros:1000},clock:()=>10});
try{const agent=await createConfiguredAgentRun({definitions,tenantId:'t',agentId:'agent',expectedVersion:1,bindings:[],registry:{invoke:async()=>null},authorizeRun:()=>true,authorizeCapability:()=>true,tokenBudget:{budget,maxTokensPerCall:60,maxCostMicrosPerCall:600,sharedCost:{ledger,actor}},createModel:()=>({invoke:async()=>new AIMessage('unused'),invokeLimitedCost:async(_messages,{callId})=>{writeFileSync(process.env.APP_MIXER_TEST_PROVIDER,JSON.stringify({callId,usedTokens:10,usedCostMicros:200}),{flag:'wx'});if(phase==='after-provider')await hold(phase);return {message:new AIMessage('Done'),usedTokens:10,usedCostMicros:200};}})});for await(const _event of agent.run({threadId:'thread',runId,messages:[{role:'user',content:'hello'}]})){}throw Error('Expected worker termination');}catch(error){process.send({error:String(error)});process.exitCode=1;budget.close();definitions.close();await pool.end();}
